import{_ as n,a0 as i,w as p,s as u,I as s,x as o,a1 as l,A as r,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"我爱开源的 7 个理由 | LCTT x X-CMD","titleTemplate":false,"description":"我爱开源的 7 个理由 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我爱开源的 7 个理由 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我爱开源的 7 个理由 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181109 7 reasons I love open source","title":"我爱开源的 7 个理由","tag":"201811","desc":""},"relativePath":"201811/20181109 7 reasons I love open source.md","filePath":"[post].md"}'),d={name:"201811/20181109 7 reasons I love open source.md"};function m(f,t,g,T,C,b){const e=i("Link");return p(),u("div",null,[t[18]||(t[18]=s("h1",{id:"我爱开源的-7-个理由",tabindex:"-1"},[o("我爱开源的 7 个理由 "),s("a",{class:"header-anchor",href:"#我爱开源的-7-个理由","aria-label":"Permalink to “我爱开源的 7 个理由”"},"​")],-1)),t[19]||(t[19]=s("blockquote",null,[s("p",null,"成为开源社区的一员绝对是一个明智之举，原因有很多。")],-1)),t[20]||(t[20]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/BUSINESS_lovework.png?itok=gmj9tqiG",alt:""})],-1)),s("p",null,[t[1]||(t[1]=o("这就是我为什么包括晚上和周末在内花费非常多的时间待在 ",-1)),l(e,{href:"https://github.com/ColinEberhardt/"},{default:r(()=>[...t[0]||(t[0]=[o("GitHub",-1)])]),_:1}),t[2]||(t[2]=o(" 上，成为开源社区的一个活跃成员。",-1))]),t[21]||(t[21]=a('<p>我参加过各种规模的项目，从个人项目到几个人的协作项目，乃至有数百位贡献者的项目，每一个项目都让我有新的受益。</p><p><img src="https://opensource.com/sites/default/files/uploads/open_source_contributions.gif" alt=""></p><p>也就是说，这里有七个原因让我为开源做出贡献：</p><ul><li><strong>它让我的技能与时俱进。</strong> 在咨询公司的管理职位工作，有时我觉得自己与创建软件的实际过程越来越远。参与开源项目使我可以重新回到我最热爱的编程之中。也使我能够体验新技术，学习新技术和语言，并且使我不被酷酷的孩子们落下。</li><li><strong>它教我如何与人打交道。</strong> 与一群素未谋面的人合作开源项目在与人交往方面能够教会你很多。你很快会发现每个人有他们自己的压力，他们自己的义务，以及不同的时间表。学习如何与一群陌生人合作是一种很好的生活技能。</li><li><strong>它使我成为一个更好的沟通者。</strong> 开源项目的维护者的时间有限。你很快就知道，要成功地贡献，你必须能够清楚、简明地表达你所做的改变、添加或修复，最重要的是，你为什么要这么做。</li><li><strong>它使我成为一个更好的开发者。</strong> 没有什么能像成百上千的其他开发者依赖你的代码一样 —— 它敦促你更加专注软件设计、测试和文档。</li><li><strong>它使我的造物变得更好。</strong> 可能开源背后最强大的观念是它允许你驾驭一个由有创造力、有智慧、有知识的个人组成的全球网络。我知道我自己一个人的能力是有限的，我不可能什么都知道，但与开源社区的合作有助于我改进我的创作。</li><li><strong>它告诉我小事物的价值。</strong> 如果一个项目的文档不清楚或不完整，我会毫不犹豫地把它做得更好。一个小小的更新或修复可能只节省开发人员几分钟的时间，但是随着用户数量的增加，您一个小小的更改可能产生巨大的价值。</li><li><strong>它使我更好的营销。</strong> 好的，这是一个奇怪的例子。有这么多伟大的开源项目在那里，感觉像一场争夺关注的拼搏。从事于开源让我学到了很多营销的价值。这不是关于讲述或创建一个华丽的网站。而是关于如何清楚地传达你所创造的，它是如何使用的，以及它带来的好处。</li></ul><p>我可以继续讨论开源是如何帮助你发展伙伴、关系和朋友的，不过你应该都知道了。有许多原因让我乐于成为开源社区的一员。</p><p>你可能想知道这些如何用于大型金融服务机构的 IT 战略。简单来说：谁不想要一个擅长与人交流和工作，具有尖端的技能，并能够推销他们的成果的开发团队呢？</p><hr>',7)),s("p",null,[t[4]||(t[4]=o("via: ",-1)),l(e,{href:"https://opensource.com/article/18/11/reasons-love-open-source"},{default:r(()=>[...t[3]||(t[3]=[o("https://opensource.com/article/18/11/reasons-love-open-source",-1)])]),_:1})]),s("p",null,[t[9]||(t[9]=o("作者：",-1)),l(e,{href:"https://opensource.com/users/colineberhardt"},{default:r(()=>[...t[5]||(t[5]=[o("Colin Eberhardt",-1)])]),_:1}),t[10]||(t[10]=o(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[6]||(t[6]=[o("lujun9972",-1)])]),_:1}),t[11]||(t[11]=o(" 译者：",-1)),l(e,{href:"https://github.com/ChiZelin"},{default:r(()=>[...t[7]||(t[7]=[o("ChiZelin",-1)])]),_:1}),t[12]||(t[12]=o(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[8]||(t[8]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=o("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[o("LCTT",-1)])]),_:1}),t[16]||(t[16]=o(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[o("Linux中国",-1)])]),_:1}),t[17]||(t[17]=o(" 荣誉推出",-1))])])}const I=n(d,[["render",m]]);export{L as __pageData,I as default};
